import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/** Silent Gate caster performance. A separate mixin so the Atomic/Fuga pose mixin and its adapters stay untouched. */
@Mixin(value=HumanoidModel.class,remap=false)
public abstract class GatePoseMixin {
    @Shadow @Final public ModelPart rightArm;
    @Shadow @Final public ModelPart leftArm;
    @Shadow @Final public ModelPart body;
    @Shadow @Final public ModelPart head;
    @Shadow @Final public ModelPart hat;
    @Inject(method="setupAnim(Lnet/minecraft/client/renderer/entity/state/HumanoidRenderState;)V",at=@At("TAIL"))
    private void godwand$gatePose(net.minecraft.client.renderer.entity.state.HumanoidRenderState state,CallbackInfo ci) {
        if(net.godwand.client.GatePose.apply(net.godwand.client.AtomicPoseFrames.entityId(state),net.godwand.client.AtomicPoseFrames.partial(state),rightArm,leftArm,body,head))hat.loadPose(head.storePose());
    }
}
